import{createProject,makeObject,objectTypes,templates,validateProject}from'./project.js';
const number=(value,fallback,min,max)=>{const n=value===undefined?fallback:Number(value);if(!Number.isFinite(n)||n<min||n>max)throw Error('Orbit proposed a value outside the supported range.');return n};
const name=value=>{if(typeof value!=='string'||!value.trim()||value.length>80)throw Error('Orbit proposed an invalid object or variable name.');return value.trim()};
export function prepareProposal(project,actions){
 if(!Array.isArray(actions)||!actions.length||actions.length>12)throw Error('Orbit must propose 1–12 supported changes.');
 const candidate=JSON.parse(JSON.stringify(project)),descriptions=[];let replacesScene=false;
 const find=target=>{const matches=candidate.objects.filter(o=>o.id===target||o.name===target);if(matches.length!==1)throw Error(`Choose a unique object named “${target}” before applying this proposal.`);return matches[0]};
 const addEvent=(o,event)=>{o.events??=[];o.events.push({id:crypto.randomUUID(),...event})};
 for(const action of actions){if(!action||typeof action.op!=='string')throw Error('Orbit returned an unsupported change.');
  if(action.op==='build_template'){if(!Object.hasOwn(templates,action.template))throw Error('Unknown game template.');const starter=createProject(candidate.name,action.template);candidate.objects=starter.objects;candidate.gravity=starter.gravity;candidate.template=starter.template;candidate.variables={...starter.variables,...candidate.variables};replacesScene=true;descriptions.push(`Replace scene objects with the ${templates[action.template]} starter.`)}
  else if(action.op==='add_object'){if(!objectTypes.includes(action.type))throw Error('Unknown object type.');const o=makeObject(action.type,number(action.x,160,-9999,9999),number(action.y,160,-9999,9999));if(action.name)o.name=name(action.name);o.w=number(action.w,o.w,1,4096);o.h=number(action.h,o.h,1,4096);candidate.objects.push(o);descriptions.push(`Add ${o.type} “${o.name}” at ${o.x}, ${o.y} (${o.w} × ${o.h}).`)}
  else if(action.op==='set_gravity'){candidate.gravity=number(action.value,1,0,10);descriptions.push(`Set world gravity to ${candidate.gravity}× Earth.`)}
  else if(action.op==='set_variable'){const key=name(action.name);if(!/^[A-Za-z][A-Za-z0-9_]{0,39}$/.test(key))throw Error('Invalid variable name.');candidate.variables??={};candidate.variables[key]=number(action.value,0,-1e6,1e6);descriptions.push(`Set ${key} to ${candidate.variables[key]}.`)}
  else if(action.op==='make_collectible'){const o=find(action.target);addEvent(o,{condition:'touch',action:'score',value:number(action.value,1,0,10000)});descriptions.push(`Make “${o.name}” add to Score when the player touches it.`)}
  else if(action.op==='enable_drag'){const o=find(action.target);addEvent(o,{condition:'pointerdown',action:'drag',value:1});descriptions.push(`Enable mouse and touch dragging for “${o.name}”.`)}
  else if(action.op==='attach'){const child=find(action.target),parent=find(action.parent);if(child===parent)throw Error('An object cannot attach to itself.');addEvent(child,{condition:'frame',action:'attach',targetId:parent.id,offsetX:number(action.offsetX,0,-4096,4096),offsetY:number(action.offsetY,0,-4096,4096),value:0});child.physics=false;child.body='trigger';descriptions.push(`Attach “${child.name}” to “${parent.name}”.`)}else if(action.op==='face_pointer'){const child=find(action.target);addEvent(child,{condition:'frame',action:'facepointer',value:number(action.value,0,-360,360)});descriptions.push(`Make “${child.name}” face the mouse or touch pointer.`)}else if(action.op==='link_platform'){const gear=find(action.target),platform=find(action.platform);if(gear.type!=='gear'||platform.type!=='platform')throw Error('Platform links need a gear and a platform.');const event={condition:'gearturn',action:'moveplatform',targetId:platform.id,axis:action.axis==='x'?'x':'y',value:number(action.value,-128,-4096,4096),turnDegrees:number(action.turnDegrees,180,1,1440),startAngle:gear.rotation||0};addEvent(gear,event);descriptions.push(`Link “${gear.name}” to move “${platform.name}” by ${event.value}px on ${event.axis.toUpperCase()}.`)}
  else throw Error(`Orbit proposed an unsupported operation: ${action.op}`);
 }
 return{candidate:validateProject(candidate),descriptions,replacesScene};
}
